package com.smartfarm360.service;

import com.smartfarm360.repository.SfTenantMembershipRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;
import java.time.LocalDate;
import java.math.BigDecimal;

@Service
public class SfCropManagementService {
 private final JdbcTemplate jdbc; private final SfTenantMembershipRepository memberships;
 public SfCropManagementService(JdbcTemplate jdbc, SfTenantMembershipRepository memberships) { this.jdbc=jdbc; this.memberships=memberships; }
 private void access(String email, Long tenantId, boolean write) { var m=memberships.findByTenantIdAndUserEmailIgnoreCaseAndActiveTrue(tenantId,email).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Tenant not found")); if(write && !List.of("OWNER","ADMIN","FARM_MANAGER").contains(m.getRole())) throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You do not have permission to change crop data"); }
 private void farm(Long tenantId, Long farmId) { if(jdbc.queryForObject("select count(*) from sf_farms where id=? and tenant_id=? and active=true",Integer.class,farmId,tenantId)==0) throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Farm not found in this tenant"); }
 private void parcel(Long tenantId, Long farmId, Long parcelId) { if(jdbc.queryForObject("select count(*) from sf_land_parcels where id=? and farm_id=? and tenant_id=? and active=true",Integer.class,parcelId,farmId,tenantId)==0) throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Land parcel not found in this farm"); }
 private void exists(String table, Long tenantId, Long id, String label) { if(id!=null && jdbc.queryForObject("select count(*) from "+table+" where id=? and tenant_id=? and active=true",Integer.class,id,tenantId)==0) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,label+" does not belong to this tenant"); }
 @Transactional public Map<String,Object> createCrop(String email,Long t,Map<String,Object> b){access(email,t,true); String name=str(b,"name"); if(name.isBlank()) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Crop name is required"); return insert("insert into sf_crop_masters(tenant_id,name,local_name,category,description) values(?,?,?,?,?) returning id",t,name,trim(b.get("localName")),trim(b.get("category")),trim(b.get("description")));}
 @Transactional(readOnly=true) public List<Map<String,Object>> crops(String email,Long t){access(email,t,false);return jdbc.queryForList("select id,tenant_id as \"tenantId\",name,local_name as \"localName\",category,description,active,created_at as \"createdAt\" from sf_crop_masters where tenant_id=? and active=true order by name",t);}
 @Transactional public Map<String,Object> createVariety(String email,Long t,Long cropId,Map<String,Object>b){access(email,t,true); exists("sf_crop_masters",t,cropId,"Crop"); String name=str(b,"name"); if(name.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Variety name is required");return insert("insert into sf_crop_varieties(tenant_id,crop_id,name,local_name,duration_days,notes) values(?,?,?,?,?,?) returning id",t,cropId,name,trim(b.get("localName")),integer(b.get("durationDays")),trim(b.get("notes")));}
 @Transactional(readOnly=true) public List<Map<String,Object>> varieties(String email,Long t,Long cropId){access(email,t,false);exists("sf_crop_masters",t,cropId,"Crop");return jdbc.queryForList("select id,tenant_id as \"tenantId\",crop_id as \"cropId\",name,local_name as \"localName\",duration_days as \"durationDays\",notes,active from sf_crop_varieties where tenant_id=? and crop_id=? and active=true order by name",t,cropId);}
 @Transactional public Map<String,Object> createSeason(String email,Long t,Map<String,Object>b){access(email,t,true);String name=str(b,"name"); LocalDate start=date(b,"startDate"),end=date(b,"endDate");if(name.isBlank()||start==null||end==null||end.isBefore(start))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Season name and a valid date range are required");return insert("insert into sf_crop_seasons(tenant_id,name,start_date,end_date,season_type) values(?,?,?,?,?) returning id",t,name,start,end,trim(b.get("seasonType")));}
 @Transactional(readOnly=true) public List<Map<String,Object>> seasons(String email,Long t){access(email,t,false);return jdbc.queryForList("select id,tenant_id as \"tenantId\",name,start_date as \"startDate\",end_date as \"endDate\",season_type as \"seasonType\",active from sf_crop_seasons where tenant_id=? and active=true order by start_date desc",t);}
 @Transactional public Map<String,Object> createCycle(String email,Long t,Map<String,Object>b){access(email,t,true);Long f=longVal(b,"farmId"),p=longVal(b,"landParcelId"),c=longVal(b,"cropId"),v=longVal(b,"varietyId"),s=longVal(b,"seasonId");farm(t,f);parcel(t,f,p);exists("sf_crop_masters",t,c,"Crop");if(v!=null && jdbc.queryForObject("select count(*) from sf_crop_varieties where id=? and tenant_id=? and crop_id=? and active=true",Integer.class,v,t,c)==0) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Variety must belong to the selected crop and tenant");exists("sf_crop_seasons",t,s,"Season");String name=str(b,"name");String cycleStatus=or(str(b,"status"),"PLANNED");if(!List.of("PLANNED","IN_PROGRESS","COMPLETED","CANCELLED").contains(cycleStatus))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid cultivation status");BigDecimal cultivated=decimal(b.get("cultivatedArea"));if(cultivated!=null&&cultivated.signum()<=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Cultivated area must be positive");LocalDate sow=date(b,"plannedSowingDate"),harv=date(b,"expectedHarvestDate");if(name.isBlank()||sow==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Cycle name and planned sowing date are required");if(harv!=null&&harv.isBefore(sow))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Expected harvest cannot be before sowing");return insert("insert into sf_cultivation_cycles(tenant_id,farm_id,land_parcel_id,crop_id,variety_id,season_id,name,planned_sowing_date,expected_harvest_date,cultivated_area,area_unit,status) values(?,?,?,?,?,?,?,?,?,?,?,?) returning id",t,f,p,c,v,s,name,sow,harv,cultivated,or(str(b,"areaUnit"),"ACRE"),cycleStatus);}
 @Transactional(readOnly=true) public List<Map<String,Object>> cycles(String email,Long t,Long f){access(email,t,false);if(f!=null)farm(t,f);String sql="select cc.id,cc.tenant_id as \"tenantId\",cc.farm_id as \"farmId\",cc.land_parcel_id as \"landParcelId\",cc.crop_id as \"cropId\",cm.name as \"cropName\",cv.name as \"varietyName\",cs.name as \"seasonName\",cc.name,cc.planned_sowing_date as \"plannedSowingDate\",cc.expected_harvest_date as \"expectedHarvestDate\",cc.cultivated_area as \"cultivatedArea\",cc.area_unit as \"areaUnit\",cc.status from sf_cultivation_cycles cc join sf_crop_masters cm on cm.id=cc.crop_id left join sf_crop_varieties cv on cv.id=cc.variety_id left join sf_crop_seasons cs on cs.id=cc.season_id where cc.tenant_id=?";return f==null?jdbc.queryForList(sql+" order by cc.created_at desc",t):jdbc.queryForList(sql+" and cc.farm_id=? order by cc.created_at desc",t,f);}
 @Transactional public Map<String,Object> createActivity(String email,Long t,Map<String,Object>b){access(email,t,true);Long cycle=longVal(b,"cycleId");exists("sf_cultivation_cycles",t,cycle,"Cultivation cycle");String type=str(b,"activityType");if(!List.of("LAND_PREPARATION","SOWING","TRANSPLANTING","FERTILIZER","PESTICIDE","IRRIGATION","WEEDING","OTHER").contains(type))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid activity type");BigDecimal q=decimal(b.get("quantity")),activityCost=decimal(b.get("cost"));if((q!=null&&q.signum()<0)||(activityCost!=null&&activityCost.signum()<0))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quantity and cost cannot be negative");LocalDate d=date(b,"activityDate");if(d==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Activity date is required");return insert("insert into sf_farm_activities(tenant_id,cycle_id,activity_type,activity_date,notes,input_name,quantity,quantity_unit,cost) values(?,?,?,?,?,?,?,?,?) returning id",t,cycle,type,d,trim(b.get("notes")),trim(b.get("inputName")),q,trim(b.get("quantityUnit")),zero(activityCost));}
 @Transactional(readOnly=true) public List<Map<String,Object>> activities(String email,Long t,Long cycle){access(email,t,false);if(cycle!=null)exists("sf_cultivation_cycles",t,cycle,"Cultivation cycle");String sql="select id,tenant_id as \"tenantId\",cycle_id as \"cycleId\",activity_type as \"activityType\",activity_date as \"activityDate\",notes,input_name as \"inputName\",quantity,quantity_unit as \"quantityUnit\",cost,created_at as \"createdAt\" from sf_farm_activities where tenant_id=?";return cycle==null?jdbc.queryForList(sql+" order by activity_date desc",t):jdbc.queryForList(sql+" and cycle_id=? order by activity_date desc",t,cycle);}
 @Transactional public Map<String,Object> createHarvest(String email,Long t,Map<String,Object>b){access(email,t,true);Long cycle=longVal(b,"cycleId");exists("sf_cultivation_cycles",t,cycle,"Cultivation cycle");LocalDate d=date(b,"harvestDate");BigDecimal qty=decimal(b.get("quantity")),value=decimal(b.get("saleValue"));String unit=str(b,"quantityUnit");if(value!=null&&value.signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Sale value cannot be negative");if(d==null||qty==null||qty.signum()<0||unit.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Harvest date, quantity and unit are required");return insert("insert into sf_harvest_records(tenant_id,cycle_id,harvest_date,quantity,quantity_unit,sale_value,notes) values(?,?,?,?,?,?,?) returning id",t,cycle,d,qty,unit,zero(value),trim(b.get("notes")));}
 @Transactional(readOnly=true) public List<Map<String,Object>> harvests(String email,Long t,Long cycle){access(email,t,false);if(cycle!=null)exists("sf_cultivation_cycles",t,cycle,"Cultivation cycle");String sql="select id,tenant_id as \"tenantId\",cycle_id as \"cycleId\",harvest_date as \"harvestDate\",quantity,quantity_unit as \"quantityUnit\",sale_value as \"saleValue\",notes,created_at as \"createdAt\" from sf_harvest_records where tenant_id=?";return cycle==null?jdbc.queryForList(sql+" order by harvest_date desc",t):jdbc.queryForList(sql+" and cycle_id=? order by harvest_date desc",t,cycle);}
 private Map<String,Object> insert(String sql,Object...args){Long id=jdbc.queryForObject(sql,Long.class,args);return Map.of("id",id);}
 private String str(Map<String,Object>b,String k){Object v=b.get(k);return v==null?"":v.toString().trim();} private String trim(Object v){if(v==null||v.toString().isBlank())return null;return v.toString().trim();} private Integer integer(Object v){try{return v==null||v.toString().isBlank()?null:Integer.valueOf(v.toString());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid integer value");}} private BigDecimal zero(BigDecimal v){return v==null?BigDecimal.ZERO:v;} private Long longVal(Map<String,Object>b,String k){Object v=b.get(k);try{return v==null||v.toString().isBlank()?null:Long.valueOf(v.toString());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid "+k);}} private BigDecimal decimal(Object v){try{return v==null||v.toString().isBlank()?null:new BigDecimal(v.toString());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid numeric value");}} private LocalDate date(Map<String,Object>b,String k){try{Object v=b.get(k);return v==null||v.toString().isBlank()?null:LocalDate.parse(v.toString());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid "+k);}} private String or(String v,String fallback){return v.isBlank()?fallback:v;}
}
